//! Differential tests for the host-independent Pi 1.3.0 compaction port.
//!
//! Fixtures are generated by `docs/provider-parity/check-compaction-pure-reference.mjs`
//! and `check-compaction-trigger-reference.mjs`, which drive the unchanged upstream
//! modules from the pinned Pi 1.3.0 install (sha256-asserted imports). Every test
//! compares the complete JSON value the reference recorded, using `json_eq` (numbers
//! by value — the contract's single allowed normalization).

use rpi_harness::compaction::pure::{
    auto_compaction_order, build_session_projection, check_compaction,
    collect_entries_for_branch_summary, compute_file_lists, estimate_context_tokens,
    estimate_projected_context_tokens, estimate_tokens, extract_file_ops_from_message,
    format_file_operations, get_summarization_failure, is_context_overflow, is_recoverable_length,
    json_eq, prepare_branch_entries, prepare_compaction, should_compact, AutoCompactionInput,
    CheckCompactionInput, FailedResponse, FileOperations, LeafSelector, PureSettings,
};
use serde_json::{json, Map, Value};

const PURE_FIXTURE: &str =
    include_str!("../../../docs/provider-parity/compaction-pure-reference.json");
const TRIGGER_FIXTURE: &str =
    include_str!("../../../docs/provider-parity/compaction-trigger-reference.json");

fn parse(fixture: &str) -> Value {
    serde_json::from_str(fixture).expect("fixture is valid JSON")
}

fn leaf_selector(row: &Value) -> LeafSelector {
    let leaf = row.get("leaf").cloned().unwrap_or(Value::Null);
    match leaf.get("mode").and_then(Value::as_str) {
        Some("explicit") => LeafSelector::ExplicitNone,
        Some("id") => LeafSelector::Id(
            leaf.get("id")
                .and_then(Value::as_str)
                .expect("id mode carries an id")
                .to_string(),
        ),
        _ => LeafSelector::Default,
    }
}

fn projection_value(projection: &rpi_harness::compaction::pure::Projection) -> Value {
    let entries: Vec<Value> = projection
        .entries
        .iter()
        .map(|entry| {
            json!({
                "sourceId": entry.source.get("id").cloned().unwrap_or(Value::Null),
                "sourceType": entry.source.get("type").cloned().unwrap_or(Value::Null),
                "messages": entry.messages,
            })
        })
        .collect();
    json!({
        "entries": entries,
        "messages": projection.messages,
        "thinkingLevel": projection.thinking_level,
        "model": projection.model,
    })
}

fn assert_rows(section: &str, rows: &[Value], mut compute: impl FnMut(&Value) -> Value) {
    assert!(!rows.is_empty(), "{section} fixture section is empty");
    for row in rows {
        let name = row
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or("<unnamed>");
        let expected = row.get("result").expect("row has a result");
        let actual = compute(row);
        assert!(
            json_eq(expected, &actual),
            "{section}/{name} mismatch\nexpected: {expected}\nactual:   {actual}"
        );
    }
}

#[test]
fn projection_matches_pi_reference() {
    let fixture = parse(PURE_FIXTURE);
    let rows = fixture["projection"].as_array().expect("projection array");
    assert_rows("projection", rows, |row| {
        let entries = row["entries"].as_array().expect("entries");
        let projection = build_session_projection(entries, &leaf_selector(row));
        projection_value(&projection)
    });
}

