#[test]
fn compute_file_lists_matches_pi_reference() {
    let fixture = parse(PURE_FIXTURE);
    let rows = fixture["utils"]["computeFileLists"]
        .as_array()
        .expect("rows");
    assert_rows("utils.computeFileLists", rows, |row| {
        let mut ops = FileOperations::default();
        for path in row["read"].as_array().expect("read") {
            ops.add_read(path.as_str().expect("path"));
        }
        for path in row["written"].as_array().expect("written") {
            ops.add_written(path.as_str().expect("path"));
        }
        for path in row["edited"].as_array().expect("edited") {
            ops.add_edited(path.as_str().expect("path"));
        }
        let (read_files, modified_files) = compute_file_lists(&ops);
        json!({ "readFiles": read_files, "modifiedFiles": modified_files })
    });
}

