fn failed_response_value(response: &Option<FailedResponse>) -> Value {
    match response {
        None => Value::Null,
        Some(FailedResponse::EntryId(id)) => Value::String(id.clone()),
        Some(FailedResponse::Unidentified) => Value::Bool(true),
    }
}

#[test]
fn check_compaction_matches_pi_reference() {
    let fixture = parse(TRIGGER_FIXTURE);
    let rows = fixture["checkCompaction"].as_array().expect("rows");
    assert_rows("checkCompaction", rows, |row| {
        let input = CheckCompactionInput {
            settings: PureSettings::from_value(&row["settings"]),
            model: row["model"].clone(),
            message: row["message"].clone(),
            branch: row["branch"].as_array().cloned().unwrap_or_default(),
            agent_messages: row["agentMessages"].as_array().cloned().unwrap_or_default(),
            assistant_entry_id: row["assistantEntryId"].as_str().map(str::to_string),
            skip_aborted_check: row["skipAbortedCheck"].as_bool().unwrap_or(true),
            overflow_recovery_attempted: row["overflowRecoveryAttempted"]
                .as_bool()
                .unwrap_or(false),
            run_returns: row["runReturns"].as_bool(),
        };
        let outcome = check_compaction(&input);
        json!({
            "calls": outcome.steps,
            "result": outcome.result,
            "overflowRecoveryAttempted": outcome.overflow_recovery_attempted,
            "failedResponse": failed_response_value(&outcome.failed_response),
        })
    });
}

#[test]
fn auto_compaction_order_matches_pi_reference() {
    let fixture = parse(TRIGGER_FIXTURE);
    let rows = fixture["autoCompaction"].as_array().expect("rows");
    assert!(!rows.is_empty(), "autoCompaction fixture section is empty");
    for row in rows {
        let name = row
            .get("name")
            .and_then(Value::as_str)
            .unwrap_or("<unnamed>");
        let input = AutoCompactionInput::from_value(row);
        let outcome = auto_compaction_order(&input);
        let mut expected = Map::new();
        for key in ["ops", "events", "result", "threw"] {
            expected.insert(
                key.to_string(),
                row.get(key).cloned().unwrap_or(Value::Null),
            );
        }
        if let Some(error_message) = row.get("errorMessage") {
            expected.insert("errorMessage".to_string(), error_message.clone());
        }
        let mut actual = Map::new();
        actual.insert("ops".into(), json!(outcome.ops));
        actual.insert("events".into(), Value::Array(outcome.events));
        actual.insert("result".into(), json!(outcome.result));
        actual.insert("threw".into(), json!(outcome.threw));
        let expected = Value::Object(expected);
        let actual = Value::Object(actual);
        assert!(
            json_eq(&expected, &actual),
            "autoCompaction/{name} mismatch\nexpected: {expected}\nactual:   {actual}"
        );
    }
}

#[test]
fn fixture_headers_are_pinned_to_pi_1_3_0() {
    for fixture in [parse(PURE_FIXTURE), parse(TRIGGER_FIXTURE)] {
        assert_eq!(
            fixture["reference"].as_str(),
            Some("Pi 1.3.0"),
            "fixture reference version"
        );
        let upstream = fixture["upstream"].as_object().expect("upstream hashes");
        assert!(!upstream.is_empty(), "upstream hashes recorded");
        for (path, hash) in upstream {
            let hash = hash.as_str().expect("hash is a string");
            assert_eq!(hash.len(), 64, "sha256 length for {path}");
        }
    }
}
